import React, { useEffect, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import styles from './conversation_style.module.css';
import { callApi } from '../api/client';

const INITIAL_PROMPT = `
You are an AI assisting with business problem definition.
The user will provide a brief business problem statement.
Your task:
1. Analyze the user's statement.
2. If you need more info, ask ONE clarifying question.
3. If you have enough, START your response with exactly:
   "Ready to formulate problem."
`.trim().toLowerCase();

const NEXT_PROMPT = `
Continuing business problem definition.
Review the conversation so far.
1. If you need more info, ask ONE clarifying question.
2. Otherwise, START your response with exactly:
   "Ready to formulate problem."
`.trim().toLowerCase();

export default function Conversation() {
  const { state } = useLocation();
  const navigate = useNavigate();
  const endRef = useRef();

  const [conversation, setConversation] = useState([]);
  const [userResponse, setUserResponse] = useState('');
  const [isFinal, setIsFinal] = useState(false);
  const [finalProblemText, setFinalProblemText] = useState('');
  const [status, setStatus] = useState('initializing'); 
  const [message, setMessage] = useState('');

  // Filter out internal system prompts & file‑detail messages
  function filterMessages(conv) {
    return conv.filter(m =>
      !m.startsWith('FileDetails:')
      && !m.toLowerCase().includes(INITIAL_PROMPT)
      && !m.toLowerCase().includes(NEXT_PROMPT)
    );
  }

  function processConversation(conv, finalProblem) {
    const filtered = filterMessages(conv);
    setConversation(filtered);

    if (finalProblem) {
      setIsFinal(true);
      setFinalProblemText(finalProblem);
      setStatus('complete');
    } else {
      setStatus('conversation');
    }
  }

  // On mount: either take initial conversation from router state or fetch it
  useEffect(() => {
    const initialConv = state?.conversation;
    const initialFinal = state?.final_problem;

    if (initialConv) {
      processConversation(initialConv, initialFinal);
      setMessage('');
    } else {
      callApi('conversation', 'GET')
        .then(data => {
          if (data.conversation) {
            processConversation(data.conversation, data.final_problem);
          } else {
            throw new Error('No conversation data');
          }
        })
        .catch(err => {
          console.error(err);
          setStatus('error');
          setMessage('Failed to load conversation.');
        });
    }
  }, [state]);

  // Auto‑scroll on new messages
  useEffect(() => {
    if (status === 'conversation') {
      endRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [conversation, status]);

  // Handle user submitting a message
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!userResponse.trim() || status !== 'conversation') return;

    setMessage('');
    setStatus('sending');
    const ans = userResponse.trim();
    setConversation(prev => [...prev, `User: ${ans}`]);
    setUserResponse('');

    try {
      const data = await callApi('conversation', 'POST', { user_response: ans });
      processConversation(data.conversation, data.final_problem);
    } catch (err) {
      console.error(err);
      setStatus('error');
      setMessage('Failed to send response.');
    }
  };

  // When fully complete, navigate after a short delay
  useEffect(() => {
    if (status === 'complete') {
      const t = setTimeout(() => navigate('/dashboard'), 1500);
      return () => clearTimeout(t);
    }
  }, [status, navigate]);

  return (
    <div className={styles.wrapper}>
      <header className={styles.header}>
        {status === 'initializing' && 'Initializing...'}
        {status === 'conversation' && !isFinal && 'Defining the Business Problem'}
        {status === 'complete' && 'Business Problem Defined'}
        {status === 'sending' && 'Sending...'}
        {status === 'error' && 'Error Occurred'}
      </header>

      <div className={styles.chatWindow}>
        {conversation.map((msg, i) => {
          const isUser = msg.startsWith('User:');
          const prefix = isUser ? 'User:' : 'AI:';
          const text = msg.replace(prefix, '').trim();
          return (
            <div
              key={i}
              className={isUser ? styles.userBubble : styles.aiBubble}
            >
              {text}
            </div>
          );
        })}
        <div ref={endRef} />
      </div>

      {status === 'conversation' && !isFinal && (
        <form className={styles.form} onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="Type your answer..."
            value={userResponse}
            onChange={e => setUserResponse(e.target.value)}
            disabled={status !== 'conversation'}
          />
          <button type="submit" disabled={!userResponse.trim()}>
            Send
          </button>
        </form>
      )}

      {status === 'complete' && (
        <div className={styles.final}>
          <h2>Final Business Problem:</h2>
          <p>{finalProblemText}</p>
          <p>✅ Redirecting to dashboard...</p>
        </div>
      )}

      {status === 'error' && <div className={styles.error}>{message}</div>}
    </div>
  );
}
